import { check, sleep } from "k6";
import { SharedArray } from "k6/data";
import exec from "k6/execution";

import { Client } from "./lib.camunda.js";

// Module-level code runs once per VU, so each VU has its own client.
const client = new Client();

// Generated by `k6/generators/generate_tariff_dmn.py` in an init container (see
// `k6.tests.dmn-large.generator` in the chart values): a ~48 MiB DMN whose top decision requires
// 11 others, and one input vector per rule of every decision table (plus random ones), each with
// the expected `rate`.
const GENERATED_DIR = __ENV.GENERATED_DIR || "../generated";
const DMN_FILENAME = "freight_tariff_48mb.dmn";
const VECTORS_FILENAME = "freight_tariff_48mb.vectors.jsonl";
const DECISION_ID = "Tariff_Rate";

const DMN_RATE = parseInt(__ENV.DMN_RATE || "1");
const DMN_RAMP_UP = __ENV.DMN_RAMP_UP || "1m";
const DMN_DURATION = __ENV.DMN_DURATION || "60d";
const DMN_PRE_ALLOCATED_VUS = parseInt(__ENV.DMN_PRE_ALLOCATED_VUS || "1");
const DMN_MAX_VUS = parseInt(__ENV.DMN_MAX_VUS || "20");

// The k6-operator initializer runs the init context without the generated files: return null
// there, and let setup() fail if the runner has no data.
function openGenerated(name, mode) {
  try {
    return open(`${GENERATED_DIR}/${name}`, mode);
  } catch (e) {
    console.warn(`Generated file ${name} not found in ${GENERATED_DIR}.`);
    return null;
  }
}

// Only setup() deploys the DMN: read it in the init context of VU 0 (setup), not in every VU.
const dmn = __VU === 0 ? openGenerated(DMN_FILENAME, "b") : null;

// Deterministic PRNG (mulberry32), so that every runner shuffles the vectors the same way.
function random(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* Parse the vectors (JSON lines) into { target, variables, rate }, in a random but fixed order.
 * `target` is the decision table the vector was built for ("random" for random traffic). */
export function parseVectors(content, seed = 20261014) {
  const vectors = content
    .split("\n")
    .filter((line) => line.trim() !== "")
    .map((line) => {
      const { id, variables, rate } = JSON.parse(line);
      return { target: id.split("#")[0], variables, rate };
    });
  const next = random(seed);
  for (let i = vectors.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1));
    [vectors[i], vectors[j]] = [vectors[j], vectors[i]];
  }
  return vectors;
}

// Shared by all the VUs of a runner: parsed once instead of once per VU.
const vectors = new SharedArray("tariff vectors", () => {
  const content = openGenerated(VECTORS_FILENAME);
  return content === null ? [] : parseVectors(content);
});

export const options = {
  // Give enough time for Camunda to be ready before continuing with the test.
  setupTimeout: "15m",
  scenarios: {
    evaluateDMN: {
      exec: "evaluateDMN",
      executor: "ramping-arrival-rate",
      startRate: 0,
      timeUnit: "1s",
      stages: [
        { target: DMN_RATE, duration: DMN_RAMP_UP },
        { target: DMN_RATE, duration: DMN_DURATION },
      ],
      preAllocatedVUs: DMN_PRE_ALLOCATED_VUS,
      maxVUs: DMN_MAX_VUS,
    },
  },
};

export function setup() {
  if (dmn === null || vectors.length === 0) {
    throw new Error(
      `Missing generated data in ${GENERATED_DIR}: did the generate-data init container run?`,
    );
  }

  client.waitUntilReady();

  const retryInterval = 5; // seconds
  while (true) {
    try {
      console.log(`Deploying DMN file: ${DMN_FILENAME}...`);
      let response = client.deploy(DMN_FILENAME, dmn);
      if (response.status !== 200) {
        throw new Error(
          `Deploy DMN file ${DMN_FILENAME} failed. Status: ${response.status}, Body: ${response.body}`,
        );
      }
      console.log(`DMN file ${DMN_FILENAME} deployed successfully.`);

      // The first evaluation on a partition parses the decision graph, which takes seconds.
      response = client.decisionDefinitionEvaluation(
        DECISION_ID,
        vectors[0].variables,
      );
      if (response.status !== 200) {
        throw new Error(
          `Decision definition evaluation ${DECISION_ID} failed. Status: ${response.status}, Body: ${response.body}`,
        );
      }
      break;
    } catch (e) {
      console.error(
        `Failed to setup test. Retrying in ${retryInterval}s...`,
        e,
      );
      sleep(retryInterval);
    }
  }

  console.log(
    `Setup completed successfully, will evaluate ${vectors.length} input vectors.`,
  );
}

/* The `rate` output of the top decision, or undefined if the response has none. */
export function evaluatedRate(response) {
  try {
    let output = JSON.parse(response.body).output;
    if (typeof output === "string") {
      output = JSON.parse(output);
    }
    return output.rate;
  } catch (e) {
    return undefined;
  }
}

export function evaluateDMN() {
  // Iterations are numbered across all the runners, so the vectors are evaluated in turn: every
  // rule is hit once per `vectors.length` iterations, in a random order.
  const vector = vectors[exec.scenario.iterationInTest % vectors.length];
  const response = client.decisionDefinitionEvaluation(
    DECISION_ID,
    vector.variables,
    { tags: { target: vector.target } },
  );
  check(
    response,
    {
      "status is 200": (r) => r.status === 200,
      "rate is expected": (r) =>
        r.status === 200 && Math.abs(evaluatedRate(r) - vector.rate) < 1e-6,
    },
    { target: vector.target },
  );
}
